-- VFDA VA Quiz App - Phase 5 database changes (VA training: unlocks, timing, proof of work).
-- GENERATED by `npm run db:bundle` from supabase/migrations/. Edit those files, not this one.
-- Paste into the Supabase SQL Editor and run after phase3b.sql.
-- Runs in one transaction: if anything fails, nothing is changed.

begin;

-- ===== 20261030140000_va_training.sql =====

-- Phase 5: VA training screens (Today, scenario screen, proof of work).
--
-- Unlocks, attempts and grades are written by the server (service role) after
-- it has checked every rule; VAs only read their own day statuses and proof
-- uploads. Scenarios reach the VA one at a time through server-only code,
-- never with answer, correct_response, critical_fail or options_rule.
--
-- Safe to run more than once.

-- A retake's version B opens no earlier than this date (the next training day).
alter table public.day_unlocks add column if not exists opens_on date;

-- Timing and honesty logs per item. served_at is when the server first showed
-- the item, so time_per_item can't be faked from the browser.
alter table public.attempt_items add column if not exists served_at timestamptz;
alter table public.attempt_items add column if not exists repeat_served_at timestamptz;
alter table public.attempt_items add column if not exists repeat_time integer;          -- seconds
alter table public.attempt_items add column if not exists paste_log jsonb not null default '[]';
alter table public.attempt_items add column if not exists fast boolean not null default false;
alter table public.attempts add column if not exists fast_finish boolean not null default false;

-- Proof of work: the file's original name and who reviewed it.
alter table public.proof_uploads add column if not exists file_name text;
alter table public.proof_uploads add column if not exists reviewed_by uuid references public.profiles (id) on delete set null;
alter table public.proof_uploads add column if not exists reviewed_at timestamptz;
create index if not exists proof_uploads_day on public.proof_uploads (va_id, schedule_day);

-- A VA adds proof only for a day that has opened, as a pending upload with
-- nothing reviewed. Files must sit in their own folder.
drop policy if exists "va adds own proof uploads" on public.proof_uploads;
create policy "va adds own proof uploads" on public.proof_uploads
  for insert to authenticated
  with check (
    private.is_me_as_va(va_id)
    and status = 'pending'
    and review_note is null
    and reviewed_by is null
    and reviewed_at is null
    and (file_path is null
         or file_path like (select private.my_office_id())::text || '/' || (select auth.uid())::text || '/%')
    and exists (
      select 1 from public.day_unlocks u
      where u.va_id = (select auth.uid())
        and u.schedule_day = proof_uploads.schedule_day
        and u.status <> 'locked'
    )
  );

-- Proof files: <office id>/<va id>/<day>/<file>, private.
insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values ('proof-of-work', 'proof-of-work', false, 52428800, array[
  'image/*', 'application/pdf', 'text/plain', 'video/mp4', 'video/quicktime', 'video/webm'])
on conflict (id) do update set
  public = false,
  file_size_limit = excluded.file_size_limit,
  allowed_mime_types = excluded.allowed_mime_types;

drop policy if exists "proof of work: admin full access" on storage.objects;
create policy "proof of work: admin full access" on storage.objects
  for all to authenticated
  using (bucket_id = 'proof-of-work' and (select private.is_admin()))
  with check (bucket_id = 'proof-of-work' and (select private.is_admin()));
drop policy if exists "proof of work: va adds own" on storage.objects;
create policy "proof of work: va adds own" on storage.objects
  for insert to authenticated
  with check (bucket_id = 'proof-of-work' and (select private.my_role()) = 'va'
              and (storage.foldername(name))[1] = (select private.my_office_id())::text
              and (storage.foldername(name))[2] = (select auth.uid())::text);
drop policy if exists "proof of work: va reads own" on storage.objects;
create policy "proof of work: va reads own" on storage.objects
  for select to authenticated
  using (bucket_id = 'proof-of-work' and (select private.my_role()) = 'va'
         and (storage.foldername(name))[1] = (select private.my_office_id())::text
         and (storage.foldername(name))[2] = (select auth.uid())::text);
drop policy if exists "proof of work: doctor reads own office" on storage.objects;
create policy "proof of work: doctor reads own office" on storage.objects
  for select to authenticated
  using (bucket_id = 'proof-of-work' and (select private.my_role()) = 'doctor'
         and (storage.foldername(name))[1] = (select private.my_office_id())::text);

-- The old database function served scenarios straight to the browser. The
-- server-only code in src/lib/va-training.ts replaces it (it also logs the
-- time each item was shown), so VAs can no longer call it.
revoke execute on function public.get_open_day_scenarios(text) from authenticated;

commit;
